argv:
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false)
$sid='gts9-pnp-id-'+[Guid]::NewGuid().ToString()
try {
 Register-CimIndicationEvent -Namespace root/cimv2 -Query "SELECT * FROM __InstanceOperationEvent WITHIN 1 WHERE TargetInstance ISA 'Win32_PnPEntity'" -SourceIdentifier $sid | Out-Null
 [ordered]@{kind='start';time=(Get-Date).ToString('o')} | ConvertTo-Json -Compress
 $watch=[Diagnostics.Stopwatch]::StartNew();$count=0
 while($watch.Elapsed.TotalSeconds -lt 50) {
   Wait-Event -SourceIdentifier $sid -Timeout 1 | Out-Null
   foreach($ev in @(Get-Event -SourceIdentifier $sid -ErrorAction SilentlyContinue)) {
     $count++;$n=$ev.SourceEventArgs.NewEvent;$d=$n.TargetInstance
     [ordered]@{kind='pnp-event';received=(Get-Date).ToString('o');event_class=$n.CimClass.CimClassName;id=$d.PNPDeviceID;name=$d.Name;present=$d.Present;status=$d.Status;problem=$d.ConfigManagerErrorCode;old=$n.PreviousInstance} | ConvertTo-Json -Depth 4 -Compress
     Remove-Event -EventIdentifier $ev.EventIdentifier
   }
 }
 [ordered]@{kind='end';time=(Get-Date).ToString('o');seconds=$watch.Elapsed.TotalSeconds;count=$count} | ConvertTo-Json -Compress
} finally { Unregister-Event -SourceIdentifier $sid -ErrorAction SilentlyContinue }
